const DefaultCommandAttempts uint32 = 3
type Client struct { session *riffdb.Session; commandAttempts uint32; causalMu sync.Mutex; readAfterCommit *uint64; trackCausalWrites bool }

func NewClient(session *riffdb.Session, commandAttempts ...uint32) (*Client, error) { attempts := DefaultCommandAttempts; if len(commandAttempts) > 1 { return nil, errors.New("invalid generated RiffDB client configuration") } else if len(commandAttempts) == 1 { attempts = commandAttempts[0] }; if session == nil || attempts < 1 || attempts > 10 { return nil, errors.New("invalid generated RiffDB client configuration") }; return &Client{session: session, commandAttempts: attempts, trackCausalWrites: true}, nil }
func DriverIdentity(role string, database ...string) riffdb.Identity { var db string; if len(database) > 0 { db = database[0] }; return riffdb.Identity{ContractLineage: ContractLineage, ContractVersion: ContractVersion, ContractBundleHash: ContractBundleHash, Role: role, Database: db} }
func Connect(ctx context.Context, socketPath string, role string, database ...string) (*Client, error) { if len(database) > 1 { return nil, errors.New("invalid generated RiffDB client configuration") }; session, err := riffdb.Connect(ctx, socketPath, DriverIdentity(role, database...)); if err != nil { return nil, err }; return NewClient(session) }
func ConnectFromEnv(ctx context.Context, prefix ...string) (*Client, error) { if len(prefix) > 1 { return nil, errors.New("invalid generated RiffDB client configuration") }; var envPrefix string; if len(prefix) == 1 { envPrefix = prefix[0] }; session, err := riffdb.ConnectFromEnv(ctx, riffdb.Identity{ContractLineage: ContractLineage, ContractVersion: ContractVersion, ContractBundleHash: ContractBundleHash}, envPrefix); if err != nil { return nil, err }; return NewClient(session) }
func (client *Client) Close() error { if client == nil || client.session == nil { return nil }; return client.session.Close() }
func (client *Client) WithReadAfterCommit(commitSequence *uint64) *Client { var copied *uint64; if commitSequence != nil { value := *commitSequence; copied = &value }; return &Client{session: client.session, commandAttempts: client.commandAttempts, readAfterCommit: copied, trackCausalWrites: client.trackCausalWrites} }
func (client *Client) CausalSession(initialCommitSequence ...uint64) *Client { var copied *uint64; if len(initialCommitSequence) > 0 { value := initialCommitSequence[0]; copied = &value } else { copied = client.LastCommitSequence() }; return &Client{session: client.session, commandAttempts: client.commandAttempts, readAfterCommit: copied, trackCausalWrites: true} }
func (client *Client) LastCommitSequence() *uint64 { client.causalMu.Lock(); defer client.causalMu.Unlock(); if client.readAfterCommit == nil { return nil }; value := *client.readAfterCommit; return &value }
func (client *Client) observeCommit(commitSequence *uint64) { if !client.trackCausalWrites || commitSequence == nil || *commitSequence == 0 { return }; client.causalMu.Lock(); if client.readAfterCommit == nil || *commitSequence > *client.readAfterCommit { value := *commitSequence; client.readAfterCommit = &value }; client.causalMu.Unlock() }

